// Two paths from (0,0) to (4,3): one never rises above y = x, the other does.
// The reflection of a bad path at its first crossing is what counts the bad ones.
size(420,340);
pen grid = gray(0.75) + 0.6;
pen diag = black + 1.2;
pen good = rgb(0.10,0.35,0.20) + 2;
pen bad = rgb(0.75,0.15,0.15) + 2;
real s = 52;
for (int i = 0; i <= 4; ++i) draw((i*s,0)--(i*s,3*s), grid);
for (int j = 0; j <= 3; ++j) draw((0,j*s)--(4*s,j*s), grid);
draw((0,0)--(3*s,3*s), diag);
draw((0,0)--(s,0)--(2*s,0)--(3*s,0)--(4*s,0)--(4*s,s), good);
draw((0,0)--(0,s)--(s,s)--(2*s,s)--(3*s,2*s)--(4*s,3*s), bad);
dot((0,0), black+2.5pt);
dot((4*s,3*s), black+2.5pt);
label("$(0,0)$", (0,0), SW);
label("$(4,3)$", (4*s,3*s), NE);
label("$y = x$", (3*s,3*s), NE);

// Two triangles sharing vertex 1: the graph whose Euler circuits are counted.
size(400,300);
pen edge = black + 1.4;
real x1 = -60, x2 = 80, y1 = 130, y2 = 60, y3 = -10;
draw((0,y1)--(x1,y2)--(x1,y3)--cycle, edge);
draw((0,y1)--(x2,y2)--(x2,y3)--cycle, edge);
dot((0,y1), black+3pt);
dot((x1,y2), black+3pt);
dot((x1,y3), black+3pt);
dot((x2,y2), black+3pt);
dot((x2,y3), black+3pt);
label("$1$", (0,y1), NE);
label("$2$", (x1,y2), NW);
label("$3$", (x1,y3), SW);
label("$4$", (x2,y2), NE);
label("$5$", (x2,y3), SE);
label("two triangles meeting at $1$", (10,-70), S);
